The total amount of time that the processor is working on or suspended by higher-priority jobs of $\tau_k$ while not working on higher priority jobs of other tasks is upper bounded by
		\begin{equation}
			\sum_{j < \ell} B_{k,j}(c,d_{k,\ell}) \leq \left(\left\lceil{\frac{d_{k,\ell}-c}{T_k}}\right\rceil-1\right) \cdot (C_k+S_k).
		\end{equation}

For $i\neq k$ the value of  $B_{k,\ell}^i(c,d_{k,\ell})$ is upper bounded by
		\begin{equation}
			B_{k,\ell}^i (c,d_{k,\ell}) \leq
				\max\left(\left\lceil{\frac{G_{k}^i+\widetilde{R}_i+r_{k,\ell}-c}{T_i}}\right\rceil, 0\right)C_i
		\end{equation}
		where $G_k^i:= \min(D_k-C_i, \Pi_k-\Pi_i)$.

Let $\mathbb{T}=\{\tau_1, \dots, \tau_n\}$ be an arbitrary-deadline task set with relative priority points $(\Pi_1, \dots, \Pi_n)$.
		We define the function $\widetilde{R}^a_k : \mathbb{R}_{\geq 0} \to \mathbb{R}_{\geq 0}$ by the assignment 
		\begin{equation}
		\begin{aligned}
		x \mapsto &\min\left(a+1, \left\lceil{\frac{D_k-x+aT_k}{T_k}}\right\rceil\right)(C_k+S_k)
		\\&+ \sum_{i \neq k} \max \left( \left\lceil{\frac{G^k_i + \widetilde{R}_i-x+aT_k}{T_i}}\right\rceil,0 \right) C_i
		+ x-aT_k.
		\end{aligned}
		\end{equation}
		If for all $k=1,\dots,n$ there exists $\tilde a_k \in \mathbb{N}_0$, such that for all $a = 0,\dots,\tilde a_k$ there exists $b^a_k \in [0,a T_k + D_k)$, such that 
		\begin{equation}
			\widetilde{R}^a_k(b^a_k) \leq D_k,
			\text{ and furthermore }
			\widetilde{R}^{\tilde a_k}_k(b^{\tilde a_k}_k) \leq T_k,
		\end{equation}
		then the task set is schedulable by EL scheduling with the given relative priority points and $\widetilde{R}_k := \max_{a = 0, \dots, \tilde a} \widetilde{R}^a_k(b^a_k)$ is an upper bound on the WCRT of $\tau_k$ for all $k$.
